def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--once', action='store_true', help='Play once instead of looping')
    parser.add_argument('--speed', type=float, default=1.0, help='Playback speed multiplier')
    args = parser.parse_args()
    if args.speed <= 0:
        parser.error('--speed must be positive')
    if os.name == 'nt':
        import ctypes
        kernel = ctypes.windll.kernel32
        handle = kernel.GetStdHandle(-11)
        mode = ctypes.c_uint32()
        if kernel.GetConsoleMode(handle, ctypes.byref(mode)):
            kernel.SetConsoleMode(handle, mode.value | 4)
    frames = json.loads(zlib.decompress(base64.b85decode(DATA)))
    out = sys.stdout
    try:
        out.write('\x1b[?25l\x1b[2J')
        out.flush()
        deadline = time.monotonic()
        while True:
            for delay, frame in frames:
                cols, rows = shutil.get_terminal_size((100, 26))
                width = max(1, min(100, cols-1, (rows-1)*4))
                height = max(1, min(25, round(width/4)))
                lines = frame.splitlines()
                art = '\n'.join(''.join(lines[y*25//height][x*100//width] for x in range(width)) for y in range(height))
                out.write('\x1b[H' + art + '\x1b[J')
                out.flush()
                deadline += delay / 1000 / args.speed
                time.sleep(max(0, deadline-time.monotonic()))
            if args.once:
                break
    except KeyboardInterrupt:
        pass
    finally:
        out.write('\x1b[?25h\n')
        out.flush()

if __name__ == '__main__':
    main()
